from yade import pack, utils, ymport
import math
import os

# 1. Define Materials
mat_steel = O.materials.append(
    FrictMat(young=2.10e+11, poisson=0.30, frictionAngle=0.337, density=7850.0)
)

# 2. Import Custom STL Drum
# This reads the STL triangles and turns them into Yade Facet bodies
stl_file = "custom_drum.stl" if os.path.exists("custom_drum.stl") else r"/home/vnews/Projects/Research project/Science_Blocks/custom_drum.stl"
drum_ids = O.bodies.append(
    ymport.stl(stl_file, material=mat_steel, color=(0.7, 0.7, 0.8), scale=1.0)
)

# 3. Add Spheres from Non-Overlapping Source Tap Inlet
spheres_to_add = [
    utils.sphere((0.00000, 0.00000, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.02390, -0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.02390, 0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.00000, -0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.00000, 0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.02390, -0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.02390, 0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.04780, 0.00000, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.02390, -0.04140, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.02390, 0.04140, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.02390, -0.04140, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.02390, 0.04140, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.04780, 0.00000, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.04780, -0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.04780, 0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.00000, -0.05520, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.00000, 0.05520, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.04780, -0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.04780, 0.02760, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.07171, -0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.07171, 0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.07171, -0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((0.07171, 0.01380, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.04780, -0.05520, 0.04250), 0.01200, material=mat_steel),
    utils.sphere((-0.04780, 0.05520, 0.04250), 0.01200, material=mat_steel),
]
drum_ball_ids = O.bodies.append(spheres_to_add)

# 4. Define Simulation Engines - Phase 1: Pre-simulation Settling
# Particles drop from source tap into resting bed before rotation starts
O.engines = [
    ForceResetter(),
    # Colliders handle contact detection between Spheres and Facets (from the STL)
    InsertionSortCollider([Bo1_Sphere_Aabb(), Bo1_Facet_Aabb()]),
    InteractionLoop(
        [Ig2_Sphere_Sphere_ScGeom(), Ig2_Facet_Sphere_ScGeom()],
        [Ip2_FrictMat_FrictMat_FrictPhys()],
        [Law2_ScGeom_FrictPhys_CundallNonViscousDamping()],
    ),
    NewtonIntegrator(gravity=(0, 0, -9.81), damping=0.4),
]

# 5. Set Time Step and Run Pre-simulation Settling
O.dt = 0.5 * utils.PWaveTimeStep()
O.saveTmp()

print("Pre-simulation settling: introducing non-overlapping particles into resting bed...")
O.run(1500, wait=True)

# 6. Phase 2: Attach Drum Rotation and Run Main DEM Simulation
O.engines = O.engines + [
    AngularEngine(
        rotationAxis=(0, 0, 1),
        angularVelocity=31.4159,  # Radians per second
        zeroPoint=(0, 0, 0),
        ids=drum_ids,  # Apply rotation exclusively to the imported STL mesh
    )
]

for e in O.engines:
    if isinstance(e, NewtonIntegrator):
        e.damping = 0.15

print("Running Yade Planetary Ball Mill Simulation (25 particles)...")
try:
    from yade import qt
    v = qt.View()
except Exception:
    pass
O.run(5000, wait=True)
print("Yade DEM Simulation completed successfully.")
